-- Read-only catalog verifier for the prepared Club Overview summary RPC.
with f as (select p.oid,p.prosrc,p.prosecdef,pg_get_function_identity_arguments(p.oid) args from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='club_overview_summary' and pg_get_function_identity_arguments(p.oid)='p_date date'), checks as (select count(*)=1 present,(select prosecdef from f) security_definer,(select prosrc from f) body,has_function_privilege('authenticated','public.club_overview_summary(date)','execute') authenticated_execute,has_function_privilege('anon','public.club_overview_summary(date)','execute') anon_execute,has_function_privilege('public','public.club_overview_summary(date)','execute') public_execute from f) select jsonb_build_object('present',present,'security_definer',security_definer,'explicit_search_path',body ilike '%set search_path=pg_catalog,public%','read_only',body !~* '\b(insert|update|delete|truncate|alter|drop)\b','tenant_authority',body ilike '%is_club_admin%','authenticated_execute',authenticated_execute,'anon_blocked',not anon_execute,'public_blocked',not public_execute,'body_hash',md5(body)) as club_overview_summary_verification from checks;
